import re
from pathlib import Path

ШЛЯХ = Path("дані") / "журнал.txt"
# Початок запису: дата і час на початку рядка
ЧАС_RE = re.compile(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})(?=\s|$)")
# Рядок-продовження виду "  ТипВинятку: повідомлення"
ВИНЯТОК_RE = re.compile(r"^\s+([^\s:]+):(?:\s|$)")

записи = []
поточний = None
with ШЛЯХ.open(encoding="utf-8-sig") as f:
    for рядок in f:
        рядок = рядок.rstrip("\r\n")
        м = ЧАС_RE.match(рядок)
        if м:
            поточний = {"час": м.group(1), "рядки": []}
            записи.append(поточний)
        elif рядок[:1].isspace() and поточний is not None:
            поточний["рядки"].append(рядок)
        # Інші рядки ігноруємо: до першого запису або не продовження

статистика = {}  # тип -> (кількість, перший час, останній час)
for запис in записи:
    тип = None
    for рядок in запис["рядки"]:
        м = ВИНЯТОК_RE.match(рядок)
        if м:
            тип = м.group(1)  # береться останній такий рядок запису
    if тип is None:
        continue
    час = запис["час"]
    if тип in статистика:
        n, перший, останній = статистика[тип]
        статистика[тип] = (n + 1, min(перший, час), max(останній, час))
    else:
        статистика[тип] = (1, час, час)

for тип, (n, перший, останній) in sorted(
    статистика.items(), key=lambda kv: (-kv[1][0], kv[0])
):
    print(f"{тип}: {n} ({перший}, {останній})")

